<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="boxDetails">
        <boxDetails />
      </div>
      <div class="dashboard">
        <div class="summary-container">
          <p>{{ $t("OrderPlanner") }}</p>
          <div class="order-summary">
            <span class="order-count">{{ totalOrders.toLocaleString() }}</span>
            <span class="order-percentage">{{ orderPercentageChange }}</span>
            <button
              class="refresh-btn"
              @click="refreshOrderData"
              title="Refresh Order Data"
              :disabled="isOrderDataLoading"
            >
              <SvgIcon
                :name="isOrderDataLoading ? 'loading' : 'refresh'"
                :class="{ rotating: isOrderDataLoading }"
              ></SvgIcon>
            </button>
          </div>
          <div>
            <canvas ref="ordersChart"></canvas>
          </div>
          <div class="month-selector">
            <span
              v-for="month in orderMonthsDisplay"
              :key="month.value"
              :class="{ active: month.value === selectedMonth }"
              @click="selectedMonth = month.value"
              :style="{
                cursor: 'pointer',
                margin: '0 4px',
                padding: '6px 14px',
                borderRadius: '5px',
                border: '1px solid #eee',
                background:
                  month.value === selectedMonth
                    ? 'var(--primary-color)'
                    : '#fff',
                color: month.value === selectedMonth ? '#fff' : '#615e83',
                fontWeight: month.value === selectedMonth ? 'bold' : 'normal',
                transition: 'background 0.2s',
              }"
            >
              {{ month.label }}
            </span>
          </div>
        </div>
        <div class="chart-container">
          <div class="Flex">
            <p>{{ $t("Sales_purchase") }}</p>
            <div class="legend">
              <span><span class="sales-dot"></span> {{ $t("Sales") }}</span>
              <button
                class="refresh-btn"
                @click="refreshSalesData"
                title="Refresh Sales Data"
                :disabled="isSalesDataLoading"
              >
                <SvgIcon
                  :name="isSalesDataLoading ? 'loading' : 'refresh'"
                  :class="{ rotating: isSalesDataLoading }"
                ></SvgIcon>
              </button>
            </div>
          </div>
          <div v-if="!isSalesDataAllZero">
            <canvas ref="salesPurchasesChart"></canvas>
          </div>
          <div
            v-else
            class="no-data-message"
            style="text-align: center; color: #888; padding: 30px 0"
          >
            لا توجد بيانات
          </div>
        </div>
      </div>
      <div class="table-container">
        <div class="headerTable">
          <div class="icon_text">
            <div class="icon">
              <SvgIcon name="resturant"></SvgIcon>
            </div>
            <p>{{ $t("restuarants") }}</p>
          </div>
          <div class="search_add">
            <div class="search">
              <input type="text" v-model="filter" :placeholder="$t('search')" />
              <SvgIcon class="svg" name="search"></SvgIcon>
            </div>
            <!-- <button class="search-button" @click="openPopup('add', {})">
              <p class="addRestbtn">{{ $t("AddRest") }}</p>
              <span class="icon">
                <SvgIcon name="add"></SvgIcon>
              </span>
            </button> -->
          </div>
        </div>
        <LoadingHere :isLoading="isLoading" />

        <div class="table-responsive">
          <table>
            <thead>
              <tr class="table-header">
                <th>
                  <div
                    style="
                      display: flex;
                      align-items: center;
                      margin-right: 10px;
                      gap: 5px;
                    "
                  >
                    <SvgIcon name="circle"></SvgIcon>

                    {{ $t("headTable1") }}
                  </div>
                </th>
                <th>{{ $t("headTable2") }}</th>
                <th>{{ $t("headTable3") }}</th>
                <th>{{ $t("headTable4") }}</th>
                <th>{{ $t("headTable5") }}</th>
                <th>{{ $t("AllProcedures") }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="(rows, index) in filteredRows"
                :key="`product-${index}`"
              >
                <td
                  style="
                    display: flex;
                    align-items: center;
                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>
                  {{ rows.id }}
                </td>
                <td>{{ rows.restName }}</td>
                <td>{{ rows.productCount }}</td>
                <td>{{ rows.orderCount }}</td>
                <td>{{ formatDate(rows.lastPurchase) }}</td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', rows)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('view', rows)">
                      <SvgIcon class="svg" name="view"></SvgIcon>
                    </div>
                    <div
                      v-if="!rows.approved"
                      class="icon"
                      @click="openPopup('approve', rows)"
                    >
                      <i class="fa-solid fa-circle-check svg approve"></i>
                    </div>
                    <div v-if="rows.approved"></div>
                    <div class="icon" @click="openPopup('delete', rows)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('commission', rows)">
                      <template
                        v-if="
                          rows.commission === 0 ||
                          rows.commission === '0' ||
                          rows.commission === '0.00' ||
                          (rows.commission &&
                            (rows.commission.value === 0 ||
                              rows.commission.value === '0.00'))
                        "
                      >
                        <i
                          class="fa-solid fa-percentage svg commission"
                          :title="$t('setCommission')"
                        ></i>
                      </template>
                      <template v-else-if="!rows.is_restaurant_have_commission">
                        <i
                          class="fa-solid fa-percentage svg commission"
                          :title="$t('setCommission')"
                        ></i>
                      </template>
                      <template v-else>
                        <i
                          class="fa-solid fa-pen-to-square svg commission"
                          :title="$t('updateCommission')"
                        ></i>
                      </template>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
  <dashboardPopup
    v-if="isPopupVisible"
    :type="popupType"
    :row="selectedRow"
    @close="closePopup"
    @save="handlePopupSave"
  />
</template>

<script>
// @ is an alias to /src
import boxDetails from "@/components/dashboard/boxDetails.vue";
import DashboardPopup from "@/components/dashboard/popus/dashboardPopup.vue";
import LoadingHere from "@/components/LoadingHere.vue";
import axios from "axios";
import SvgIcon from "@/components/SvgIcon.vue";
import { getLocalizedNameWithI18n } from "@/utils/localization.js";

export default {
  name: "dashboardHome",
  components: {
    boxDetails,
    LoadingHere,
    DashboardPopup,
    SvgIcon,
  },

  data() {
    return {
      filter: "",
      rows: [
        // More products here
      ],
      isPopupVisible: false,
      popupType: "",
      selectedRow: {},
      isLoading: false,
      salesChart: null,
      ordersChart: null,
      resizeTimeout: null,
      chartsInitialized: false,
      salesChartData: {
        labels: [],
        sales: [],
        purchases: [],
      },
      orderChartData: {
        labels: [],
        orders: [],
      },
      isSalesDataLoading: false,
      isOrderDataLoading: false,
      isUnmounted: false, // <-- Add this flag
      selectedMonth: "", // Track the selected month (format: 'YYYY-MM')
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.restName === "string" &&
            row.restName.toLowerCase().includes(searchTerm)) ||
          (row.id && row.id.toString().toLowerCase().includes(searchTerm))
        );
      });
    },
    totalSales() {
      return this.salesChartData.sales.reduce((sum, sale) => sum + sale, 0);
    },
    salesPercentageChange() {
      if (this.salesChartData.sales.length < 2) return "+0%";

      const currentPeriod = this.salesChartData.sales
        .slice(-3)
        .reduce((sum, sale) => sum + sale, 0);
      const previousPeriod = this.salesChartData.sales
        .slice(-6, -3)
        .reduce((sum, sale) => sum + sale, 0);

      if (previousPeriod === 0) return "+0%";

      const change = ((currentPeriod - previousPeriod) / previousPeriod) * 100;
      return `${change >= 0 ? "+" : ""}${Math.round(change)}%`;
    },
    totalOrders() {
      return this.orderChartData.orders.reduce((sum, order) => sum + order, 0);
    },
    orderPercentageChange() {
      if (this.orderChartData.orders.length < 2) return "+0%";

      const currentPeriod = this.orderChartData.orders
        .slice(-3)
        .reduce((sum, order) => sum + order, 0);
      const previousPeriod = this.orderChartData.orders
        .slice(-6, -3)
        .reduce((sum, order) => sum + order, 0);

      if (previousPeriod === 0) return "+0%";

      const change = ((currentPeriod - previousPeriod) / previousPeriod) * 100;
      return `${change >= 0 ? "+" : ""}${Math.round(change)}%`;
    },
    isSalesDataAllZero() {
      return this.salesChartData.sales.length === 0;
    },
    isOrdersDataAllZero() {
      return this.orderChartData.orders.length === 0;
    },
    orderMonths() {
      // Extract unique months from orderChartData.labels (which are formatted as 'MMM DD') and orderChartData raw data
      // We'll use the raw API data for accuracy
      const months = new Set();
      if (
        this.orderChartData &&
        this.orderChartData.labels &&
        this.orderChartData.labels.length > 0 &&
        this.orderChartData.orders &&
        this.orderChartData.orders.length > 0
      ) {
        // Try to get months from the original API data if available
        // We'll assume the API data is stored in this._orderRawData (set in fetchOrderChartData)
        if (this._orderRawData && Array.isArray(this._orderRawData)) {
          this._orderRawData.forEach((item) => {
            if (item.date) {
              const d = new Date(item.date);
              if (!isNaN(d)) {
                const monthStr =
                  d.getFullYear() +
                  "-" +
                  String(d.getMonth() + 1).padStart(2, "0");
                months.add(monthStr);
              }
            }
          });
        }
      }
      // Return sorted months (descending, most recent first)
      return Array.from(months).sort().reverse();
    },
    orderMonthsDisplay() {
      // Map orderMonths to { value: 'YYYY-MM', label: 'MonthName YYYY' }
      return this.orderMonths.map((monthStr) => {
        const [year, month] = monthStr.split("-");
        const date = new Date(Number(year), Number(month) - 1, 1);
        // Use current locale for month name
        const monthName = date.toLocaleString(
          this.$i18n.locale === "ar" ? "ar" : "en",
          { month: "long" }
        );
        return { value: monthStr, label: monthName + " " + year };
      });
    },
    filteredOrderChartData() {
      // Filter the orderChartData by selectedMonth
      if (!this.selectedMonth || !this._orderRawData)
        return { labels: [], orders: [] };
      const filtered = this._orderRawData.filter((item) => {
        if (!item.date) return false;
        const d = new Date(item.date);
        if (isNaN(d)) return false;
        const monthStr =
          d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
        return monthStr === this.selectedMonth;
      });
      return {
        labels: filtered.map((item) => {
          const d = new Date(item.date);
          return d.toLocaleDateString(
            this.$i18n.locale === "ar" ? "ar-SA-u-ca-gregory" : "en-US",
            { month: "short", day: "numeric" }
          );
        }),
        orders: filtered.map((item) => item.total_orders || 0),
      };
    },
  },
  async mounted() {
    this.isLoading = true;
    this.fetchUserData(); // Fetch user data dynamically
    this.FetchRows(); // Fetch rows dynamically
    this.fetchSalesChartData(); // Fetch sales chart data
    this.fetchOrderChartData(); // Fetch order chart data

    // Wait for DOM to be ready and ensure canvas elements exist
    await this.$nextTick();

    // Additional wait to ensure DOM is fully rendered
    await new Promise((resolve) => setTimeout(resolve, 200));

    // Test Chart.js availability
    if (typeof window.Chart === "undefined") {
      console.error("Chart.js is not available. Please check the import.");
      return;
    }

    // Add global error handler for Chart.js
    this.addChartErrorHandler();

    // Initialize charts with proper error handling
    this.initializeCharts();

    // Retry chart initialization if it fails
    setTimeout(() => {
      if (!this.chartsInitialized) {
        console.log("Retrying chart initialization...");
        this.initializeCharts();
      }
    }, 1000);

    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }

    // Add resize listener for responsive charts
    window.addEventListener("resize", this.handleResize);
  },
  beforeUnmount() {
    // Set unmounted flag to prevent further chart operations
    this.isUnmounted = true;
    // Clean up charts to prevent memory leaks
    this.destroyCharts();
    // Remove resize listener
    window.removeEventListener("resize", this.handleResize);
    // Clear any remaining timeouts
    if (this.resizeTimeout) {
      clearTimeout(this.resizeTimeout);
    }
    // Stop all Chart.js animations (defensive)
    if (window.Chart && window.Chart.instances) {
      Object.values(window.Chart.instances).forEach((chart) => {
        if (chart && typeof chart.stop === "function") {
          chart.stop();
        }
      });
    }
  },
  watch: {
    selectedMonth() {
      // When the selected month changes, re-render the orders chart
      if (this.chartsInitialized && !this.isUnmounted) {
        console.log("Watcher: selectedMonth changed to", this.selectedMonth);
        this.renderOrdersChart();
      }
    },
  },
  methods: {
    addChartErrorHandler() {
      // Add global error handler for Chart.js context issues
      const originalError = console.error;
      console.error = (...args) => {
        const errorMessage = args.join(" ");
        if (
          errorMessage.includes("Cannot read properties of null") &&
          errorMessage.includes("save")
        ) {
          console.warn(
            "Chart.js context error detected and handled:",
            errorMessage
          );
          return;
        }
        originalError.apply(console, args);
      };
    },
    destroyCharts() {
      try {
        if (this.salesChart) {
          if (
            this.salesChart.canvas &&
            document.contains(this.salesChart.canvas) &&
            this.salesChart.ctx
          ) {
            this.salesChart.destroy();
          }
          this.salesChart = null;
        }
        if (this.ordersChart) {
          if (
            this.ordersChart.canvas &&
            document.contains(this.ordersChart.canvas) &&
            this.ordersChart.ctx
          ) {
            this.ordersChart.destroy();
          }
          this.ordersChart = null;
        }
        this.chartsInitialized = false;
      } catch (error) {
        console.error("Error destroying charts:", error);
      }
    },
    initializeCharts() {
      try {
        if (this.chartsInitialized) {
          return;
        }

        // Check if Chart is properly imported
        if (typeof window.Chart === "undefined") {
          console.error(
            "Chart is not defined. Chart.js may not be properly imported."
          );
          return;
        }

        // Ensure Chart.js is fully loaded
        if (!window.Chart.prototype || !window.Chart.prototype.constructor) {
          console.error("Chart.js is not properly initialized");
          return;
        }

        // Check if canvas elements exist
        const salesCanvas = this.$refs.salesPurchasesChart;
        const ordersCanvas = this.$refs.ordersChart;

        if (!salesCanvas || !ordersCanvas) {
          console.log("Canvas elements not found, retrying in 500ms...");
          setTimeout(() => this.initializeCharts(), 500);
          return;
        }

        // Render charts with fallback data if needed
        this.renderSalesPurchasesChart();
        this.renderOrdersChart();
        this.chartsInitialized = true;
        console.log("Charts initialized successfully");
      } catch (error) {
        console.error("Error initializing charts:", error);
        // Reset initialization flag to allow retry
        this.chartsInitialized = false;
      }
    },
    handleResize() {
      // Debounce resize events for better performance
      clearTimeout(this.resizeTimeout);
      this.resizeTimeout = setTimeout(() => {
        try {
          if (
            this.salesChart &&
            this.salesChart.canvas &&
            typeof this.salesChart.resize === "function"
          ) {
            this.salesChart.resize();
          }
          if (
            this.ordersChart &&
            this.ordersChart.canvas &&
            typeof this.ordersChart.resize === "function"
          ) {
            this.ordersChart.resize();
          }
        } catch (error) {
          console.error("Error resizing charts:", error);
        }
      }, 250);
    },
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    fetchSalesChartData() {
      this.isSalesDataLoading = true;
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-sales-chart",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          console.log('Sales API response:', response.data);
          if (this.isUnmounted) return;
          this.isSalesDataLoading = false;
          const data = response.data;
          if (data && data.status && data.data && Array.isArray(data.data)) {
            this.salesChartData.labels = data.data
              .map((item) => {
                const date = new Date(item.date);
                return date.toLocaleDateString("en-US", {
                  month: "short",
                  day: "numeric",
                });
              })
              .filter((label) => label && label !== "Invalid Date");
            this.salesChartData.sales = data.data.map((item) => {
              const total = item.total || 0;
              return typeof total === "number" && !isNaN(total) ? total : 0;
            });
            this.salesChartData.purchases = data.data.map((item) => {
              const total = item.total || 0;
              const purchaseValue = Math.floor(total * 0.7);
              return typeof purchaseValue === "number" && !isNaN(purchaseValue)
                ? purchaseValue
                : 0;
            });
            this.synchronizeChartData();
            if (this.chartsInitialized && !this.isUnmounted) {
              this.renderSalesPurchasesChart();
            }
            if (this.$toast) {
              this.$toast.success("Sales data updated successfully!");
            }
          } else {
            if (this.$toast) {
              this.$toast.error("Failed to load sales data");
            }
            // No fallback data, just clear chart data
            this.salesChartData.labels = [];
            this.salesChartData.sales = [];
            this.salesChartData.purchases = [];
            if (this.chartsInitialized && !this.isUnmounted) {
              this.renderSalesPurchasesChart();
            }
          }
        })
        .catch(() => {
          if (this.isUnmounted) return;
          this.isSalesDataLoading = false;
          if (this.$toast) {
            this.$toast.error("Failed to load sales data.");
          }
          // No fallback data, just clear chart data
          this.salesChartData.labels = [];
          this.salesChartData.sales = [];
          this.salesChartData.purchases = [];
          if (this.chartsInitialized && !this.isUnmounted) {
            this.renderSalesPurchasesChart();
          }
        });
    },
    fetchOrderChartData() {
      this.isOrderDataLoading = true;
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-order-count",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          console.log('Order API response:', response.data);
          if (this.isUnmounted) return;
          this.isOrderDataLoading = false;
          const data = response.data;
          if (data && data.status && data.data && Array.isArray(data.data)) {
            // Store the raw API data for month filtering
            this._orderRawData = data.data;
            this.orderChartData.labels = data.data
              .map((item) => {
                const date = new Date(item.date);
                return date.toLocaleDateString("en-US", {
                  month: "short",
                  day: "numeric",
                });
              })
              .filter((label) => label && label !== "Invalid Date");
            this.orderChartData.orders = data.data.map((item) => {
              const totalOrders = item.total_orders || 0;
              return typeof totalOrders === "number" && !isNaN(totalOrders)
                ? totalOrders
                : 0;
            });
            // If no month is selected, select the most recent month
            if (!this.selectedMonth && data.data.length > 0) {
              // Find the most recent date
              const mostRecent = data.data.reduce((a, b) =>
                new Date(a.date) > new Date(b.date) ? a : b
              );
              const d = new Date(mostRecent.date);
              if (!isNaN(d)) {
                this.selectedMonth =
                  d.getFullYear() +
                  "-" +
                  String(d.getMonth() + 1).padStart(2, "0");
              }
            }
            if (this.chartsInitialized && !this.isUnmounted) {
              this.renderOrdersChart();
            }
            if (this.$toast) {
              this.$toast.success("Order data updated successfully!");
            }
          } else {
            if (this.$toast) {
              this.$toast.error("Failed to load order data");
            }
            // No fallback data, just clear chart data
            this.orderChartData.labels = [];
            this.orderChartData.orders = [];
            this._orderRawData = [];
            if (this.chartsInitialized && !this.isUnmounted) {
              this.renderOrdersChart();
            }
          }
        })
        .catch(() => {
          if (this.isUnmounted) return;
          this.isOrderDataLoading = false;
          if (this.$toast) {
            this.$toast.error("Failed to load order data.");
          }
          // No fallback data, just clear chart data
          this.orderChartData.labels = [];
          this.orderChartData.orders = [];
          this._orderRawData = [];
          if (this.chartsInitialized && !this.isUnmounted) {
            this.renderOrdersChart();
          }
        });
    },
    refreshSalesData() {
      console.log("Refreshing sales data...");
      this.fetchSalesChartData();
    },
    refreshOrderData() {
      console.log("Refreshing order data...");
      this.fetchOrderChartData();
    },
    FetchRows() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-all-restaurants",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`, // Add the Authorization header
            },
          }
        )
        .then((response) => {
          console.log('Restaurants API response:', response.data);
          if (this.isUnmounted) return;
          this.isLoading = false;
          console.log("Restaurant Response:", response.data); // Log the response
          const data = response.data;

          // Check if data exists and has the expected structure
          if (data && data.status && data.data && Array.isArray(data.data)) {
            this.rows = data.data
              .filter((item) => item && item.id) // Filter out items without id
              .map((item) => ({
                id: item.id || `restaurant_${Date.now()}_${Math.random()}`,
                restName:
                  getLocalizedNameWithI18n(item.name, this.$i18n) || "N/A",
                email: item.email || "",
                phone: item.phone || "",
                productCount: item.total_products || 0,
                orderCount: item.total_orders || 0,
                lastPurchase: item.last_order || "No orders yet",
                approved: Boolean(
                  item.approved && item.approved !== 0 && item.approved !== "0"
                ),
                is_restaurant_have_commission:
                  item.is_restaurant_have_commission || false,
                commission: item.commission || null,
              }));
            console.log("Processed rows:", this.rows);
            // Debug approved status
            this.rows.forEach((row, index) => {
              console.log(
                `Row ${index}: ID=${row.id}, Name=${row.restName}, Approved=${
                  row.approved
                } (type: ${typeof row.approved})`
              );
            });
          } else {
            console.error(
              "Failed to fetch rows data: Invalid data structure",
              data
            );
            this.rows = []; // Set empty array if data is invalid
          }
        })
        .catch((error) => {
          if (this.isUnmounted) return;
          this.isLoading = false; // Set loading state to false
          console.error("Error fetching rows data:", error);
          this.rows = []; // Set empty array on error
        });
    },
    renderSalesPurchasesChart() {
      try {
        if (this.isUnmounted) return;
        const canvas = this.$refs.salesPurchasesChart;
        if (!canvas || !document.contains(canvas)) {
          console.warn("Sales chart canvas not found or not in DOM");
