import { createApp } from "vue";
import App from "./App.vue";
import router from "./router";
import "./assets/main.css";
import store from "./store";
import i18n from "./i18n";
import Toast from 'vue-toastification';
import 'vue-toastification/dist/index.css';
import VueTelInput from 'vue3-tel-input';
import 'vue3-tel-input/dist/vue3-tel-input.css';
import 'axios';
import { library } from '@fortawesome/fontawesome-svg-core';
import { fas } from '@fortawesome/free-solid-svg-icons'; // Solid icons
import { far } from '@fortawesome/free-regular-svg-icons'; // Regular icons
import { fab } from '@fortawesome/free-brands-svg-icons'; // Brand icons
import { FontAwesomeIcon } from '@fortawesome/vue-fontawesome';
import { Chart, registerables } from 'chart.js';

// Comprehensive monkey-patch for Chart.js clipArea to prevent null context errors globally
try {
  // Patch on Chart.helpers.clipArea
  if (Chart && Chart.helpers && Chart.helpers.clipArea) {
    const originalClipArea = Chart.helpers.clipArea;
    Chart.helpers.clipArea = function(ctx, area) {
      if (!ctx) return;
      return originalClipArea(ctx, area);
    };
  }
  // Patch on Chart.helpers['helpers.dataset'].clipArea
  if (Chart && Chart.helpers && Chart.helpers['helpers.dataset'] && Chart.helpers['helpers.dataset'].clipArea) {
    const originalClipArea = Chart.helpers['helpers.dataset'].clipArea;
    Chart.helpers['helpers.dataset'].clipArea = function(ctx, area) {
      if (!ctx) return;
      return originalClipArea(ctx, area);
    };
  }
  // Patch on Chart.prototype.clipArea (for some builds)
  if (Chart && Chart.prototype && Chart.prototype.clipArea) {
    const originalClipArea = Chart.prototype.clipArea;
    Chart.prototype.clipArea = function(ctx, area) {
      if (!ctx) return;
      return originalClipArea.call(this, ctx, area);
    };
  }
  // Patch on window.Chart if available (for UMD builds)
  if (typeof window !== 'undefined' && window.Chart && window.Chart.helpers && window.Chart.helpers.clipArea) {
    const originalClipArea = window.Chart.helpers.clipArea;
    window.Chart.helpers.clipArea = function(ctx, area) {
      if (!ctx) return;
      return originalClipArea(ctx, area);
    };
  }
} catch (e) {
  console.warn('Chart.js comprehensive monkey-patch for clipArea failed:', e);
}

// Register Chart.js components globally
Chart.register(...registerables);

// Make Chart.js available globally
window.Chart = Chart;

// Patch the prototype method used by Chart.js for all chart instances
try {
  if (window.Chart && window.Chart.prototype) {
    // Find all methods named 'clipArea' on the prototype chain and patch them
    let proto = window.Chart.prototype;
    while (proto) {
      if (Object.prototype.hasOwnProperty.call(proto, 'clipArea')) {
        const originalClipArea = proto.clipArea;
        proto.clipArea = function(ctx, area) {
          if (!ctx) return;
          return originalClipArea.call(this, ctx, area);
        };
      }
      proto = Object.getPrototypeOf(proto);
    }
  }
} catch (e) {
  console.warn('Chart.js prototype monkey-patch for clipArea failed:', e);
}

library.add(fas, far, fab);

/* import specific icons */
import { faUserSecret } from '@fortawesome/free-solid-svg-icons';

/* add icons to the library */
library.add(faUserSecret);

const app = createApp(App);

// Make router and store available globally for axios interceptor
window.router = router;
window.store = store;

app.use(Toast)
  .component('font-awesome-icon', FontAwesomeIcon)
  .use(store)
  .use(VueTelInput)
  .use(i18n)
  .use(router)
  .mount("#app");

// Make toast available globally after app is mounted
// We'll access it through the app instance when needed
window.getToast = () => app.config.globalProperties.$toast;

  