            @input="onPhoneInput"
            @blur="onPhoneBlur"
            :disabled="mode === 'view'"
            class="custom-tel-input"
          />
          <span class="error-message" v-if="errors.phone">{{ errors.phone }}</span>
        </div>
        <div class="input-container">
          <label>{{ $t("email") }}</label>
          <input 
            v-model="localCustomer.email" 
            :disabled="mode === 'view'"
