          />
          <span class="error-message" v-if="errors.email">{{ errors.email }}</span>
        </div>
        <div class="input-container" v-if="mode === 'add'">
          <label class="checkbox-label">
            <input type="checkbox" v-model="localCustomer.verify_phone" />
            <span>{{ $t('verify_phone') }}</span>
          </label>
        </div>
        <div class="input-container" v-if="mode === 'add'">
          <label class="checkbox-label">
            <input type="checkbox" v-model="localCustomer.verify_email" />
            <span>{{ $t('verify_email') }}</span>
          </label>
        </div>
        <div class="input-container" v-if="mode === 'add'">
          <label>{{ $t("password") }}</label>
          <input
            v-model="localCustomer.password"
            :disabled="mode === 'view'"
            :class="{ 'error-input': errors.password }"
            type="password"
          />
          <span class="error-message" v-if="errors.password">{{ errors.password }}</span>
        </div>
        <!-- The rest of the fields only for view mode -->
        <div class="input-container" v-if="mode === 'view'">
          <label>{{ $t("OrderCount") }}</label>
          <input
            v-model="localCustomer.ordersCount"
            type="number"
            :disabled="mode === 'view'"
            :class="{ 'error-input': errors.ordersCount }"
          />
          <span class="error-message" v-if="errors.ordersCount">{{ errors.ordersCount }}</span>
        </div>
        <div class="input-container" v-if="mode === 'view'">
          <label>{{ $t("TotalSpending") }}</label>
          <input
            v-model="localCustomer.ordersTotal"
            type="number"
            :disabled="mode === 'view'"
            :class="{ 'error-input': errors.ordersTotal }"
          />
          <span class="error-message" v-if="errors.ordersTotal">{{ errors.ordersTotal }}</span>
        </div>
        <div class="input-container" v-if="mode === 'view'">
          <label>{{ $t("LastOrderDate") }}</label>
          <input
            v-model="localCustomer.LastOrderDate"
            type="date"
            :disabled="mode === 'view'"
          />
          <span class="error-message" v-if="errors.LastOrderDate">{{ errors.LastOrderDate }}</span>
        </div>
      </div>
      <p style="text-align: center" v-if="mode === 'delete'">
        {{ $t("confirmDeleteCustomer") }}
      </p>
      <p v-if="mode === 'delete'" style="text-align: center; color: #545454">
        {{ $t("deleteWarning") }}
      </p>
      <div class="popup-actions">
        <button v-if="mode === 'add'" @click="save">{{ $t("Save") }}</button>
        <button v-if="mode === 'edit'" @click="save">{{ $t("Save") }}</button>
        <button
          style="background-color: #f02116; color: #ffffff"
          v-if="mode === 'delete'"
          @click="confirmDelete"
        >
          {{ $t("delete") }}
        </button>
        <button @click="$emit('close')">{{ $t("Cancel") }}</button>
      </div>
    </div>
  </div>
</template>

<script>
import { useToast } from "vue-toastification";
import axios from "@/axios";

export default {
  name: "customerPopup",
  props: {
    mode: { type: String, required: true },
    customer: {
      type: Object,
      default: () => ({
        id: null,
        name: "",
        email: "",
        phone: "",
        password: "",
        verify_phone: false,
        verify_email: false,
        // For view mode only
        ...(this && this.mode === 'view' ? {
          ordersCount: 0,
          ordersTotal: 0,
          LastOrderDate: new Date().toISOString().split("T")[0],
        } : {})
      }),
    },
  },
  data() {
    return {
      localCustomer: {
        ...this.customer,
        verify_phone: this.mode === 'add' ? false : !!this.customer.verify_phone,
        verify_email: this.mode === 'add' ? false : !!this.customer.verify_email,
      },
      errors: {
        name: null,
        email: null,
        phone: null,
        password: null,
        ...(this.mode === 'view' ? {
          ordersCount: null,
          ordersTotal: null,
          LastOrderDate: null,
        } : {})
      },
      toast: null,
      loading: false,
      isPhoneValid: true, // Track phone validation state
    };
  },
  created() {
    this.toast = useToast();
  },
  watch: {
    customer: {
      immediate: true,
      async handler(newCustomer) {
        if (this.mode !== 'add') {
          Object.assign(this.localCustomer, {
            ...newCustomer,
            verify_phone: !!newCustomer.verify_phone,
            verify_email: !!newCustomer.verify_email,
          });
          // Fetch customer details from API if in view mode and id exists
          if (this.mode === 'view' && newCustomer && newCustomer.id) {
            await this.fetchCustomerById(newCustomer.id);
          }
        }
      },
    },
  },
  methods: {
    async fetchCustomerById(id) {
      this.loading = true;
      try {
        const token = localStorage.getItem('authToken');
        const response = await axios.get(`https://backend.alaqdk.com/api/v1/admin/users/${id}`, {
          headers: {
            'Accept-Language': this.$i18n.locale,
            Authorization: `Bearer ${token}`,
          },
        });
        if (response.data && response.data.data && response.data.data.user) {
          const data = response.data.data;
          const user = data.user;
          this.localCustomer = {
            ...this.localCustomer,
            name: user.name || '',
            email: user.email || '',
            phone: user.phone || '',
            ordersCount: data.total_orders || 0,
            ordersTotal: data.total_purchases || 0,
            LastOrderDate: user.created_at ? user.created_at.split(' ')[0] : new Date().toISOString().split('T')[0],
            // Add more fields if needed
          };
        } else {
          this.toast && this.toast.error(this.$t('validation.loadError'));
        }
      } catch (error) {
        this.toast && this.toast.error(error.response?.data?.message || this.$t('validation.loadError'));
      } finally {
        this.loading = false;
      }
    },
    onPhoneInput(phoneObj) {
      if (phoneObj && typeof phoneObj === 'object' && phoneObj.number !== undefined) {
        this.localCustomer.phone = phoneObj.number;
        this.isPhoneValid = phoneObj.valid;
      } else if (phoneObj && typeof phoneObj === 'object' && phoneObj.target) {
        const inputValue = phoneObj.target.value;
        if (inputValue) {
          this.localCustomer.phone = inputValue;
          this.isPhoneValid = inputValue.length >= 7;
        }
      }
      if (this.localCustomer.phone) {
        this.localCustomer.phone = this.localCustomer.phone.replace(/[\s\-()]/g, '');
      }
      if (this.errors.phone) {
        delete this.errors.phone;
      }
    },
    onPhoneBlur(phoneObj) {
      if (phoneObj && typeof phoneObj === 'object' && phoneObj.number !== undefined) {
        this.localCustomer.phone = phoneObj.number;
        this.isPhoneValid = phoneObj.valid;
      } else if (phoneObj && typeof phoneObj === 'object' && phoneObj.target) {
        const inputValue = phoneObj.target.value;
        if (inputValue) {
          this.localCustomer.phone = inputValue;
          this.isPhoneValid = inputValue.length >= 7;
        }
      }
      if (this.localCustomer.phone) {
        this.localCustomer.phone = this.localCustomer.phone.replace(/[\s\-()]/g, '');
      }
    },
    validateForm() {
      let isValid = true;
      
      // Reset errors
      this.errors = {
        name: null,
        email: null,
        phone: null,
        password: null,
        ...(this.mode === 'view' ? {
          ordersCount: null,
          ordersTotal: null,
          LastOrderDate: null,
        } : {})
      };

      // Validate required fields for add/edit
      if (!this.localCustomer.name || !this.localCustomer.name.trim()) {
        this.errors.name = this.$t("validation.required");
        if (this.toast) this.toast.error(this.$t("validation.required") + ": " + this.$t("CustomerName"));
        isValid = false;
      }
      if (!this.localCustomer.phone || this.localCustomer.phone.trim() === '') {
        this.errors.phone = this.$t("validation.required");
        isValid = false;
      } else if (this.localCustomer.phone.length < 7) {
        this.errors.phone = this.$t("validation.invalidPhone");
        isValid = false;
      } else {
        delete this.errors.phone;
      }
      if (!this.localCustomer.email || !this.localCustomer.email.trim()) {
        this.errors.email = this.$t("validation.required");
        if (this.toast) this.toast.error(this.$t("validation.required") + ": " + this.$t("email"));
        isValid = false;
      } else {
        // Validate email format
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(this.localCustomer.email)) {
          this.errors.email = this.$t("validation.invalidEmail");
          if (this.toast) this.toast.error(this.$t("validation.invalidEmail"));
          isValid = false;
        }
      }
      if (this.mode === 'add') {
        if (!this.localCustomer.password || !this.localCustomer.password.trim()) {
          this.errors.password = this.$t("validation.required");
          if (this.toast) this.toast.error(this.$t("validation.required") + ": " + this.$t("Password"));
          isValid = false;
        } else if (this.localCustomer.password.length < 6) {
          this.errors.password = this.$t("validation.passwordLength");
          if (this.toast) this.toast.error(this.$t("validation.passwordLength"));
          isValid = false;
        }
      }

      // Validate date format (LastOrderDate)
      if (this.mode === 'view') {
        if (!this.localCustomer.LastOrderDate || this.localCustomer.LastOrderDate.trim() === '') {
          this.errors.LastOrderDate = this.$t("validation.invalidDate");
          if (this.toast) {
            this.toast.error(this.$t("validation.invalidDate"));
          }
          isValid = false;
        } else {
          const date = new Date(this.localCustomer.LastOrderDate);
          if (isNaN(date.getTime())) {
            this.errors.LastOrderDate = this.$t("validation.invalidDate");
            if (this.toast) {
              this.toast.error(this.$t("validation.invalidDate"));
            }
            isValid = false;
          } else {
            this.errors.LastOrderDate = null;
          }
        }

        // Validate numeric fields
        if (this.localCustomer.ordersCount === '' || isNaN(Number(this.localCustomer.ordersCount))) {
          this.errors.ordersCount = this.$t("validation.numeric");
          if (this.toast) {
            this.toast.error(this.$t("validation.numeric") + ": " + this.$t("OrderCount"));
          }
          isValid = false;
        }

        if (this.localCustomer.ordersTotal === '' || isNaN(Number(this.localCustomer.ordersTotal))) {
          this.errors.ordersTotal = this.$t("validation.numeric");
          if (this.toast) {
            this.toast.error(this.$t("validation.numeric") + ": " + this.$t("TotalSpending"));
          }
          isValid = false;
        }
      }

      return isValid;
    },
    save() {
      if (!this.validateForm()) {
        this.$emit("error", this.errors);
        if (this.toast) this.toast.error(this.$t("validation.formErrors"));
        return;
      }
      if (this.mode === 'add') {
        this.loading = true;
        const payload = {
          name: this.localCustomer.name,
          email: this.localCustomer.email,
          phone: this.localCustomer.phone,
          password: this.localCustomer.password,
          role: 'user',
          verify_phone: this.localCustomer.verify_phone ? 1 : 0,
          verify_email: this.localCustomer.verify_email ? 1 : 0,
        };
        axios.post('https://backend.alaqdk.com/api/v1/admin/users/store/new', payload)
          .then(response => {
            this.$emit("save", { ...this.localCustomer, id: response.data?.id || null });
            if (this.toast) this.toast.success(this.$t("validation.saveSuccess"));
            this.$emit('close');
          })
          .catch(error => {
            if (error.response && error.response.data && error.response.data.message) {
              this.toast.error(error.response.data.message);
            } else {
              this.toast.error(this.$t("validation.saveError"));
            }
          })
          .finally(() => {
            this.loading = false;
          });
      } else if (this.mode === 'edit') {
        this.loading = true;
        const payload = {
          _method: 'put',
          name: this.localCustomer.name,
          email: this.localCustomer.email,
          phone: this.localCustomer.phone,
        };
        axios.post(`https://backend.alaqdk.com/api/v1/admin/users/${this.localCustomer.id}`, payload)
          .then(() => {
            this.$emit("save", { ...this.localCustomer });
            if (this.toast) this.toast.success(this.$t("validation.saveSuccess"));
            this.$emit('close');
          })
          .catch(error => {
            if (error.response && error.response.data && error.response.data.message) {
              this.toast.error(error.response.data.message);
            } else {
              this.toast.error(this.$t("validation.saveError"));
            }
          })
          .finally(() => {
            this.loading = false;
          });
      } else {
        this.$emit("save", { ...this.localCustomer, verify_phone: this.localCustomer.verify_phone ? 1 : 0, verify_email: this.localCustomer.verify_email ? 1 : 0 });
        if (this.toast) this.toast.success(this.$t("validation.saveSuccess"));
      }
    },
    async confirmDelete() {
      if (!this.localCustomer.id) return;
      this.loading = true;
      try {
        const token = localStorage.getItem('authToken');
        await axios.delete(`https://backend.alaqdk.com/api/v1/admin/users/${this.localCustomer.id}`, {
          headers: {
            'Accept-Language': this.$i18n.locale,
            Authorization: `Bearer ${token}`,
          },
        });
        this.toast && this.toast.success(this.$t('validation.deletedSuccess'));
        this.$emit('delete', this.localCustomer.id);
        this.$emit('close');
      } catch (error) {
        this.toast && this.toast.error(error.response?.data?.message || this.$t('validation.deleteError'));
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

