<template>
  <div class="popup-overlay" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="popup-content">
      <div class="header">
        <div class="semi-header">
          <svg
            width="22"
            height="22"
            viewBox="0 0 22 22"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M8.5 6C8.5 5.44772 8.94771 5 9.5 5L16.5 5C17.0523 5 17.5 5.44772 17.5 6C17.5 6.55229 17.0523 7 16.5 7L9.5 7C8.94771 7 8.5 6.55229 8.5 6Z"
              fill="#FBB040"
            />
            <path
              d="M9.5 9C8.94771 9 8.5 9.44772 8.5 10C8.5 10.5523 8.94771 11 9.5 11H13C13.5523 11 14 10.5523 14 10C14 9.44772 13.5523 9 13 9H9.5Z"
              fill="#FBB040"
            />
            <path
              fill-rule="evenodd"
              clip-rule="evenodd"
              d="M18.2563 0.366058C17.3926 0.249942 16.3014 0.249969 14.9781 0.250001L10.931 0.250001C9.60769 0.249969 8.5164 0.249942 7.65275 0.366058C6.746 0.487966 5.9452 0.753753 5.304 1.39495C4.66281 2.03615 4.39702 2.83695 4.27511 3.74369C4.15899 4.60736 4.15902 5.6986 4.15906 7.02195L4.15906 14.3091C4.15906 14.5919 4.15906 14.7334 4.07119 14.8212C3.98332 14.9091 3.8419 14.9091 3.55905 14.9091L3.08344 14.9091C2.65936 14.9089 2.22951 14.9088 1.87244 14.9682C1.44525 15.0393 0.998763 15.2128 0.654575 15.6424C0.333301 16.0435 0.236304 16.4787 0.251513 16.9104C0.263525 17.2512 0.350162 17.6332 0.429535 17.9831C0.626294 18.8528 0.98532 19.8094 1.56295 20.5101C2.16342 21.2384 3.01879 21.75 4.12398 21.75L17.8347 21.75C19.2282 21.75 20.278 21.161 20.9321 20.1638C21.5448 19.23 21.75 18.033 21.75 16.8636L21.75 7.02197C21.75 5.69861 21.75 4.60737 21.6339 3.74369C21.512 2.83695 21.2462 2.03615 20.605 1.39495C19.9638 0.753753 19.163 0.487966 18.2563 0.366058ZM6.71377 14.9091C6.43093 14.9091 6.28951 14.9091 6.20164 14.8213C6.11377 14.7334 6.11377 14.592 6.11377 14.3091L6.11377 7.09095C6.11377 5.68126 6.11585 4.72229 6.21239 4.00417C6.30516 3.31417 6.46873 2.99458 6.68624 2.77707C6.90376 2.55955 7.22334 2.39599 7.91335 2.30322C8.63147 2.20667 9.59043 2.20459 11.0001 2.20459L14.9092 2.20459C16.3189 2.20459 17.2779 2.20667 17.996 2.30322C18.686 2.39599 19.0056 2.55955 19.2231 2.77707C19.4406 2.99458 19.6042 3.31417 19.697 4.00417C19.7935 4.72229 19.7956 5.68126 19.7956 7.09096L19.7956 16.8637C19.7956 17.8532 19.6135 18.6108 19.298 19.0918C19.024 19.5095 18.6048 19.7955 17.8349 19.7955C17.4034 19.7955 17.0724 19.6191 16.7819 19.2668C16.4685 18.8867 16.2187 18.3115 16.06 17.6103C15.9543 17.143 15.8508 16.6854 15.7463 16.3635C15.6437 16.0476 15.4758 15.6313 15.1061 15.3364C14.7596 15.0599 14.3672 14.9763 14.044 14.9415C13.7424 14.909 13.3743 14.9091 12.9832 14.9091L6.71377 14.9091Z"
              fill="#FBB040"
            />
          </svg>
          <h3 v-if="type === 'view'">{{ $t("OrderDetails") }}</h3>
          <h3 v-if="type === 'add'">{{ $t("AddOrder") }}</h3>
          <h3 v-if="type === 'edit'">{{ $t("EditOrder") }}</h3>
          <h3 v-if="type === 'delete'">{{ $t("DeleteOrder") }}</h3>
          <h3 v-if="type === 'commission'">{{ $t("setCommission") }}</h3>
        </div>
        <button class="close-button" @click="$emit('close')">X</button>
      </div>
      <div class="form" v-if="type !== 'delete' && type !== 'commission'">
        <div class="input-container">
          <label>{{ $t("CustomerName") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">{{ formData.customerName }}</div>
          </template>
          <template v-else>
            <select 
              v-model="formData.customer_id"
              @change="onCustomerChange"
            >
              <option value="">{{ $t("SelectCustomer") }}</option>
              <option 
                v-for="customer in customers" 
                :key="customer.user.id" 
                :value="customer.user.id"
              >
                {{ customer.user.name }} ({{ customer.user.email }})
              </option>
            </select>
          </template>
        </div>
        <div class="input-container">
          <label>{{ $t("Phone") }}</label>
          <input v-model="formData.phone" :disabled="type === 'view'" />
        </div>
        <div class="input-container">
          <label>{{ $t("RestaurantName") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">{{ getRestaurantName(formData.restaurant_id) }}</div>
          </template>
          <template v-else>
            <select 
              v-model="formData.restaurant_id"
              @change="onRestaurantChange"
            >
              <option value="">{{ $t("SelectRestaurant") }}</option>
              <option 
                v-for="restaurant in restaurants" 
                :key="restaurant.id" 
                :value="restaurant.id"
              >
                {{ restaurant.name }}
              </option>
            </select>
          </template>
        </div>
        <div class="input-container">
          <label>{{ $t("RestaurantBranch") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">{{ formData.restaurant_branch }}</div>
          </template>
          <template v-else>
           <select v-model="formData.restaurant_branch_id" @change="onBranchChange">
              <option value="">{{ $t("SelectBranch") }}</option>
              <option v-for="branch in restaurantBranches" :key="branch.id" :value="branch.id">
                {{ branch.name }}
              </option>
            </select>
          </template>
        </div>
        <div class="input-container">
          <label>{{ $t("Meals") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">
              <ul>
                <li v-for="item in formData.order_items" :key="item.meal_id">
                  {{ item.meal_name }} - {{ item.quantity }}
                </li>
              </ul>
            </div>
          </template>
          <template v-else>
            <div style="display: flex; gap: 8px; align-items: center;">
              <select v-model="selectedMealId">
                <option value="">{{ $t("SelectMeals") }}</option>
                <option v-for="meal in meals" :key="meal.id" :value="meal.id">
                  {{ meal.name }} - {{ meal.price }}
                </option>
              </select>
              <input type="number" v-model.number="selectedMealQuantity" min="1" style="width: 70px;" :placeholder="$t('EnterQuantity')" />
              <button type="button" @click="addMealToOrder" class="save-style">{{ $t('Add') }}</button>
            </div>
            <ul>
              <li v-for="(item, idx) in formData.order_items" :key="item.meal_id">
                {{ getMealById(item.meal_id)?.name || '' }} - {{ item.quantity }}
                <button type="button" @click="removeMealFromOrder(idx)">×</button>
              </li>
            </ul>
          </template>
        </div>
        <div class="input-container">
          <label>{{ $t("TotalPrice") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">{{ formData.total_price }}</div>
          </template>
          <template v-else>
            <input :value="calculateTotalPrice()" :disabled="true" />
          </template>
        </div>
        <div class="input-container">
          <label>{{ $t("PaymentMethod") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">{{ formData.payment_method_name }}</div>
          </template>
          <template v-else>
            <select 
              v-model="formData.payment_method_id"
            >
              <option value="">{{ $t("SelectPaymentMethod") }}</option>
              <option 
                v-for="method in paymentMethods" 
                :key="method.id" 
                :value="method.id"
              >
                {{ method.name }}
              </option>
            </select>
          </template>
        </div>
        <div class="input-container">
          <label>{{ $t("OrderStatus") }}</label>
          <template v-if="type === 'view'">
            <div class="view-text">{{ getStatusLabel(formData.status) }}</div>
          </template>
          <template v-else>
            <select v-model="formData.status" @change="onStatusChange">
              <option value="waiting">{{ $t('Waiting') }}</option>
              <option value="approved">{{ $t('Approved') }}</option>
              <option value="processing">{{ $t('Processing') }}</option>
              <option value="on_delivery">{{ $t('OnDelivery') }}</option>
              <option value="delivered">{{ $t('Delivered') }}</option>
              <option value="cancelled">{{ $t('Cancelled') }}</option>
            </select>
          </template>
        </div>
      </div>

      <!-- Commission Form -->
      <div class="form" v-if="type === 'commission'">
        <div class="input-container">
          <label>{{ $t("Type") }}</label>
          <select v-model="commissionData.type">
            <option value="percentage">{{ $t('Percentage') }}</option>
            <option value="manual">{{ $t('Manual') }}</option>
          </select>
        </div>
        <div class="input-container">
          <label>{{ $t("Value") }}</label>
          <input type="number" v-model.number="commissionData.value" min="0" />
        </div>
      </div>

      <p style="text-align: center; color: black" v-if="type === 'delete'">
        {{ $t("confirmDeleteOrder") }}
      </p>
      <p style="text-align: center" v-if="type === 'delete'">
        {{ $t("deleteWarning") }}
      </p>

      <div class="popup-actions">
        <button
          style="background-color: #f02116"
          v-if="type === 'delete'"
          @click="deleteOrder"
        >
          {{ $t("delete") }}
        </button>
        <button v-if="type === 'add' || type === 'edit'" @click="saveOrder">
          {{ $t("Save") }}
        </button>
        <!-- Commission Save Button -->
        <button v-if="type === 'commission'" @click="saveCommission">
          {{ $t('Save') }}
        </button>
        <button @click="$emit('close')">{{ $t("Cancel") }}</button>
      </div>
    </div>
  </div>
</template>

<script>
import { useToast } from "vue-toastification";
import axios from "../../../axios.js";
import { getLocalizedNameWithI18n } from "@/utils/localization.js";

export default {
  props: {
    type: String,
    data: {
      type: Object,
      default: () => ({}),
    },
  },
  computed: {
    rowData() {
      return this.data;
    },
  },
  data() {
    return {
      formData: {
        ...this.data,
        address_description: Array.isArray(this.data.address_description)
          ? this.data.address_description
          : this.data.address_description
          ? [this.data.address_description] // Convert to array if it's a string
          : [], // Default to an empty array
        status: this.data.status || "processing", // Ensure status has a default value
        isCancelled: this.data.isCancelled || false, // Add isCancelled property
        restaurant_id: this.data.restaurant_id || "", // Add restaurant_id property
        quantity: 1, // Remove global quantity, handled per meal
        payment_method_id: this.data.payment_method_id || "", // Add payment_method_id property
        customer_id: this.data.customer_id || "", // Add customer_id property
        restaurant_branch_id: this.data.restaurant_branch_id || "", // Add restaurant_branch_id property
        order_items: this.data.order_items || [], // Array of { meal_id, quantity }
        address_description_text: this.data.address_description_text || '',
      },
      orderDetailInput: "",
      statuses: ["processing", "on_delivery", "delivered"], // Use English status values to match the table
      restaurants: [], // Array to store restaurants from API
      paymentMethods: [], // Array to store payment methods from API
      customers: [], // Array to store customers from API
      restaurantBranches: [], // Array to store branches for selected restaurant
      meals: [], // Array to store meals for selected branch
      toast: useToast(),
      selectedMealId: '',
      selectedMealQuantity: 1,
      commissionData: this.type === 'commission'
        ? {
            type: 'percentage',
            value: 0,
            commissionable_type: 'order',
            commissionable_id: this.data.id || ''
          }
        : {
            type: 'percentage',
            value: 0,
            commissionable_type: 'order',
            commissionable_id: ''
          },
    };
  },
  async mounted() {
    // Fetch restaurants, payment methods, and customers when component is mounted
    await Promise.all([
      this.fetchRestaurants(),
      this.fetchPaymentMethods(),
      this.fetchCustomers()
    ]);
  },
  watch: {
    type(newType) {
      if (newType === 'commission') {
        this.commissionData.commissionable_id = this.data.id || '';
        if (this.data && this.data.commission) {
          this.commissionData.type = this.data.commission.type || 'percentage';
          this.commissionData.value = this.data.commission.value || 0;
        }
      }
    },
    data: {
      immediate: true,
      handler(newData) {
        this.formData = {
          ...newData,
          address_description: Array.isArray(newData.address_description)
            ? newData.address_description
            : newData.address_description
            ? [newData.address_description] // Convert to array if it's a string
            : [], // Default to an empty array
          status: newData.status || "processing", // Ensure status has a default value
          isCancelled: newData.isCancelled || false, // Add isCancelled property
          restaurant_id: newData.restaurant_id || "", // Add restaurant_id property
          quantity: newData.quantity || 1, // Add quantity property
          payment_method_id: newData.payment_method_id || "", // Add payment_method_id property
          customer_id: newData.customer_id || "", // Add customer_id property
          restaurant_branch_id: newData.restaurant_branch_id || "", // Add restaurant_branch_id property
          order_items: newData.order_items || [], // Add order_items property
          address_description_text: newData.address_description_text || '',
        };
        if (this.type === 'commission') {
          this.commissionData.commissionable_id = newData.id || '';
          if (newData && newData.commission) {
            this.commissionData.type = newData.commission.type || 'percentage';
            this.commissionData.value = newData.commission.value || 0;
          }
        }
      },
    },
    'formData.meal_id': function() {
      this.updateTotalPrice();
    },
    'formData.quantity': function() {
      this.updateTotalPrice();
    },
  },
  methods: {
    getRestaurantName(id) {
      const found = this.restaurants.find(r => r.id == id);
      return found ? found.name : '';
    },
    getPaymentMethodName(id) {
      const found = this.paymentMethods.find(m => m.id == id);
      return found ? found.name : '';
    },
    async fetchRestaurants() {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get(
          "v1/admin/dashboard/get-approved-restaurants",
          {
            headers: {
              "Accept-Language": this.$i18n.locale,
              Authorization: `Bearer ${token}`,
            },
          }
        );
        
        if (response.data.status) {
          this.restaurants = response.data.data.map((item) => ({
            id: item.restaurant.id,
            name: getLocalizedNameWithI18n(item.restaurant.name, this.$i18n) || "N/A",
          }));
        } else {
          console.error("Failed to fetch restaurants:", response.data.message);
          this.toast.error(this.$t("FailedToFetchRestaurants"));
        }
      } catch (error) {
        console.error("Error fetching restaurants:", error);
        this.toast.error(this.$t("FailedToFetchRestaurants"));
      }
    },
    async fetchPaymentMethods() {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get(
          "v1/admin/payment-methods",
          {
            headers: {
              "Accept-Language": this.$i18n.locale,
              Authorization: `Bearer ${token}`,
            },
          }
        );
        
        if (response.data.status) {
          this.paymentMethods = response.data.data.map((method) => ({
            id: method.id,
            name: method.name || "N/A",
          }));
        } else {
          console.error("Failed to fetch payment methods:", response.data.message);
          this.toast.error(this.$t("FailedToFetchPaymentMethods"));
        }
      } catch (error) {
        console.error("Error fetching payment methods:", error);
        this.toast.error(this.$t("FailedToFetchPaymentMethods"));
      }
    },
         async fetchCustomers() {
       try {
         const token = localStorage.getItem("authToken");
         const response = await axios.get(
           "v1/admin/dashboard/get-all-users",
           {
             headers: {
               "Accept-Language": this.$i18n.locale,
               Authorization: `Bearer ${token}`,
             },
           }
         );
         
         if (response.data.status) {
           this.customers = response.data.data
             .filter(item => item.user.role === 'user')
             .map((item) => ({
               user: {
                 id: item.user.id,
                 name: item.user.name || "N/A",
                 email: item.user.email,
                 phone: item.user.phone,
               },
             }));
         } else {
           console.error("Failed to fetch customers:", response.data.message);
           this.toast.error(this.$t("FailedToFetchCustomers"));
         }
       } catch (error) {
         console.error("Error fetching customers:", error);
         this.toast.error(this.$t("FailedToFetchCustomers"));
       }
     },
    async onRestaurantChange() {
      // When restaurant is selected, update the restaurant_branch field
      const selectedRestaurant = this.restaurants.find(r => r.id == this.formData.restaurant_id);
      if (selectedRestaurant) {
        // Fetch branches for the selected restaurant
        await this.fetchRestaurantBranches(this.formData.restaurant_id);
        // Reset branch selection and meals
        this.formData.restaurant_branch_id = '';
        this.meals = [];
        this.formData.meal_id = '';
      } else {
        this.restaurantBranches = [];
        this.formData.restaurant_branch_id = '';
        this.meals = [];
        this.formData.meal_id = '';
      }
      console.log("Selected restaurant ID:", this.formData.restaurant_id);
    },
    async fetchRestaurantBranches(restaurantId) {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get(
          `v1/admin/branches-by-resturant/${restaurantId}`,
          {
            headers: {
              "Accept-Language": this.$i18n.locale,
              Authorization: `Bearer ${token}`,
            },
          }
        );
        if (response.data.status) {
          this.restaurantBranches = response.data.data.map((branch) => ({
            id: branch.id,
            name: branch.name || "N/A",
          }));
        } else {
          this.restaurantBranches = [];
          this.toast.error(this.$t("FailedToFetchBranches"));
        }
      } catch (error) {
        this.restaurantBranches = [];
        this.toast.error(this.$t("FailedToFetchBranches"));
      }
    },
    async onBranchChange() {
      if (this.formData.restaurant_branch_id) {
        await this.fetchMeals(this.formData.restaurant_branch_id);
        this.formData.meal_id = '';
      } else {
        this.meals = [];
        this.formData.meal_id = '';
      }
    },
    async fetchMeals(branchId) {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get(
          `v1/admin/meals/meals-by-resturant-branch/${branchId}`,
          {
            headers: {
              "Accept-Language": this.$i18n.locale,
              Authorization: `Bearer ${token}`,
            },
          }
        );
        if (response.data.status) {
          this.meals = response.data.data.map((meal) => ({
            id: meal.id,
            name: meal.product?.name || "N/A",
            price: meal.price_after_offer || meal.product?.price || "0.00",
          }));
        } else {
          this.meals = [];
          this.toast.error(this.$t("FailedToFetchMeals"));
        }
      } catch (error) {
        this.meals = [];
        this.toast.error(this.$t("FailedToFetchMeals"));
      }
    },
    getBranchName(id) {
      const found = this.restaurantBranches.find(b => b.id == id);
      return found ? found.name : '';
    },
    getMealNames(ids) {
      return this.meals.filter(m => ids.includes(m.id)).map(m => m.name).join(', ');
    },
    getMealById(id) {
      return this.meals.find(m => m.id == id);
    },
    updateTotalPrice() {
      const meal = this.getMealById(this.formData.meal_id);
      const quantity = Number(this.formData.quantity) || 1;
      if (meal && meal.price) {
        this.formData.total_price = (parseFloat(meal.price) * quantity).toFixed(2);
      } else {
        this.formData.total_price = '';
      }
    },
         onCustomerChange() {
       const selectedCustomer = this.customers.find(c => c.user.id == this.formData.customer_id);
       if (selectedCustomer) {
         this.formData.customerName = selectedCustomer.user.name;
         this.formData.phone = selectedCustomer.user.phone;
       }
       console.log("Selected customer ID:", this.formData.customer_id);
     },
    onStatusChange() {
      // Emit status change to parent component for immediate update
      if (this.type === 'edit') {
        this.$emit('statusChange', {
          id: this.formData.id,
          status: this.formData.status
        });
      }
    },
    addMealToOrder() {
      if (!this.selectedMealId || !this.selectedMealQuantity || this.selectedMealQuantity < 1) {
        this.toast.error(this.$t('SelectMeals') + ' & ' + this.$t('EnterQuantity'));
        return;
      }
      // Prevent duplicate meals
      const exists = this.formData.order_items.some(item => item.meal_id == this.selectedMealId);
      if (exists) {
        this.toast.error(this.$t('MealAlreadyAdded'));
        return;
      }
      this.formData.order_items.push({
        meal_id: this.selectedMealId,
        quantity: this.selectedMealQuantity
      });
      this.selectedMealId = '';
      this.selectedMealQuantity = 1;
    },
    removeMealFromOrder(idx) {
      this.formData.order_items.splice(idx, 1);
    },
    calculateTotalPrice() {
      let total = 0;
      for (const item of this.formData.order_items) {
        const meal = this.getMealById(item.meal_id);
        if (meal && meal.price) {
          total += parseFloat(meal.price) * item.quantity;
        }
      }
      return total.toFixed(2);
    },
    validateForm() {
      if (
        !this.formData.customer_id ||
        this.formData.customer_id === ""
      ) {
        this.toast.error(this.$t("CustomerName") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.phone || this.formData.phone.trim() === "") {
        this.toast.error(this.$t("Phone") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.order_items || this.formData.order_items.length === 0) {
        this.toast.error(this.$t("Meals") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.restaurant_branch_id || this.formData.restaurant_branch_id === "") {
        this.toast.error(this.$t("RestaurantBranch") + " " + this.$t("isRequired"));
        return false;
      }
      if (!this.formData.payment_method_id || this.formData.payment_method_id === "") {
        this.toast.error(this.$t("PaymentMethod") + " " + this.$t("isRequired"));
        return false;
      }
      return true;
    },
    async saveOrder() {
      if (this.validateForm()) {
        try {
          const token = localStorage.getItem("authToken");
          if (this.type === 'add') {
            // Add new order - send to API
            const orderData = {
              user_id: Number(this.formData.customer_id),
              restaurant_branch_id: Number(this.formData.restaurant_branch_id),
              phone: this.formData.phone,
              payment_method_id: Number(this.formData.payment_method_id),
              status: this.formData.status || 'waiting',
              order_items: this.formData.order_items.map(item => ({
                meal_id: Number(item.meal_id),
                quantity: Number(item.quantity)
              })),
            };
            const response = await axios.post(
              'v1/admin/orders/store',
              orderData,
              {
                headers: {
                  "Accept-Language": this.$i18n.locale,
                  Authorization: `Bearer ${token}`,
                },
              }
            );
            if (response.data.status) {
              this.toast.success(this.$t("OrderSavedSuccessfully"));
              this.$emit("save", orderData);
            } else {
              this.toast.error(response.data.message || this.$t("FailedToSaveOrder"));
            }
          } else if (this.type === 'edit') {
            // Update existing order using the new endpoint and JSON body
            const orderData = {
              user_id: Number(this.formData.customer_id),
              restaurant_branch_id: Number(this.formData.restaurant_branch_id),
              address_description: this.formData.address_description_text || '',
              phone: this.formData.phone,
              payment_method_id: Number(this.formData.payment_method_id),
              status: this.formData.status,
              order_items: this.formData.order_items.map(item => ({
                meal_id: Number(item.meal_id),
                quantity: Number(item.quantity)
              })),
            };
            const response = await axios.put(
              `https://backend.alaqdk.com/api/v1/admin/orders/admin-update/${this.formData.id}`,
              orderData,
              {
                headers: {
                  "Accept-Language": this.$i18n.locale,
                  Authorization: `Bearer ${token}`,
                  'Content-Type': 'application/json',
                },
              }
            );
            if (response.data.status) {
              this.toast.success(this.$t("OrderUpdatedSuccessfully"));
              this.$emit("save", { ...this.formData, ...orderData });
            } else {
              this.toast.error(response.data.message || this.$t("FailedToUpdateOrder"));
            }
          }
        } catch (error) {
          console.error("Error saving order:", error);
          this.toast.error(this.$t("FailedToSaveOrder"));
        }
      }
    },
    deleteOrder() {
      this.$emit("delete", this.formData.id);
      this.toast.success(this.$t("OrderDeletedSuccessfully"));
    },
    getStatusLabel(status) {
      switch (status) {
        case 'waiting': return this.$t('Waiting');
        case 'approved': return this.$t('Approved');
        case 'processing': return this.$t('Processing');
        case 'on_delivery': return this.$t('OnDelivery');
        case 'delivered': return this.$t('Delivered');
        case 'cancelled': return this.$t('Cancelled');
        default: return status;
      }
    },
    async saveCommission() {
      try {
        const token = localStorage.getItem("authToken");
        const commissionData = {
          type: this.commissionData.type,
          value: parseFloat(this.commissionData.value),
          commissionable_type: 'order',
          commissionable_id: this.commissionData.commissionable_id,
        };
        let response;
        if (this.data.commission && this.data.commission.id) {
          // Update existing commission
          response = await axios.put(
            `https://backend.alaqdk.com/api/v1/admin/commissions/${this.data.commission.id}`,
            commissionData,
            {
              headers: {
                "Accept-Language": this.$i18n.locale,
                Authorization: `Bearer ${token}`,
                'Content-Type': 'application/json',
              },
            }
          );
        } else {
          // Create new commission
          response = await axios.post(
            "https://backend.alaqdk.com/api/v1/admin/commissions",
            commissionData,
            {
              headers: {
                "Accept-Language": this.$i18n.locale,
                Authorization: `Bearer ${token}`,
                'Content-Type': 'application/json',
              },
            }
          );
        }
        if (response.data.status) {
          this.toast.success(this.$t('CommissionSavedSuccessfully'));
          this.$emit('save', { commission: { ...commissionData } });
          this.$emit('close');
        } else {
          this.toast.error(response.data.message || this.$t('FailedToSaveCommission'));
        }
      } catch (error) {
        this.toast.error(error.response?.data?.message || this.$t('FailedToSaveCommission'));
      }
    },
  },
};
</script>

